solution.code:
#include <stdio.h>

int is_power_of_two(unsigned int n) {
    return n > 0 && (n & (n - 1)) == 0;
}

int main() {
    unsigned int tests[] = {0, 2, 3, 8};
    for (int i = 0; i < 4; i++) {
        printf("%u -> %d\n", tests[i], is_power_of_two(tests[i]));
    }
    return 0;
}
